function recordUpdate(reqSysId, reqActionName, reqActionUrl) {
    var gr = new GlideRecord('sn_imt_core_health_and_safety_requirement');
    if (gr.get(reqSysId)) {
        gr.action_name = reqActionName;
        gr.action_url = reqActionUrl;
        gr.action_visibility = 'visible_when_false';
        gr.actionable = false;
        gr.update();
    }
}
